echo "K1: dpofix6"; export RUNNER_TRACKING_ID=""
N=/workspace/nox; D=$N/ops/dpo; A=$N/agent/autotrain; ts=$(date +%s); W=$(mktemp -d)
base64 -d > $W/char_cycle.sh <<'B64'

B64
base64 -d > $W/mix_data.py <<'B64'

B64
bash -n $W/char_cycle.sh || { echo SYNTAX_FAIL; exit 0; }; python3 -m py_compile $W/mix_data.py || { echo PYFAIL; exit 0; }
cp -a $D/char_cycle.sh $D/char_cycle.sh.bak_fix6_$ts; cp -a $D/mix_data.py $D/mix_data.py.bak_fix6_$ts
cp $W/char_cycle.sh $D/char_cycle.sh; cp $W/mix_data.py $D/mix_data.py; chmod +x $D/char_cycle.sh; echo installed
touch $N/state/body_ttft_upgrade.off; echo "ttft_off=$([ -e $N/state/body_ttft_upgrade.off ] && echo 1 || echo 0)"
# known_good не поднимался (все эксперты на CPU при полном VRAM) -> подменить рабочим гибридом ncmoe22; оригинал в бэкап
cp -a $A/donor_hybrid.cmd.known_good $A/donor_hybrid.cmd.known_good.bak_fix6_$ts; cmp -s $A/donor_hybrid.cmd.liska_ncmoe22 $A/donor_hybrid.cmd.known_good || cp $A/donor_hybrid.cmd.liska_ncmoe22 $A/donor_hybrid.cmd.known_good; echo "known_good_is_22=$(cmp -s $A/donor_hybrid.cmd.liska_ncmoe22 $A/donor_hybrid.cmd.known_good && echo 1 || echo 0)"
echo "gen_hold_files=$(ls $N/state/*gen_hold* $N/state/orch/*gen_hold* 2>/dev/null | wc -l)"
rm -f $N/state/p3/dpo_vram_abort 2>/dev/null
for P in $(pgrep -f 'bash .*char_cycle.sh|python -I train_dpo.py'); do kill -9 $P; done; sleep 4
echo "lock_free=$(flock -n $D/char_cycle.lock true && echo 1 || echo 0) 8104=$(curl -s -o /dev/null -m 5 -w %{http_code} http://127.0.0.1:8104/health)"
cd $D && setsid nohup bash $D/char_cycle.sh >> $A/char_cycle.log 2>&1 < /dev/null &
for i in 1 2 3 4 5 6; do sleep 30; pgrep -f 'python -I train_dpo.py' >/dev/null && break; done
sleep 60
grep -h 'mix rows' $D/run7.log | tail -1
echo "procs: $(ps -eo stat,etimes,args | grep -E 'train_dpo|body_restart' | grep -v grep | awk '{print $1,$2,$3,$4,$5}' | sed 's#/[^ ]*/##g' | tr '\n' ';')"
UM=$(nvidia-smi --query-gpu=memory.used,memory.total --format=csv,noheader,nounits); echo "vram $UM pct=$(( ${UM%%,*}*100/${UM##*, } )) 8104=$(curl -s -o /dev/null -m 5 -w %{http_code} http://127.0.0.1:8104/health)"
tail -4 $A/char_cycle.log | cut -c1-150
rm -rf $W; echo END
